"""Arps decline curve fitting. - This is generated by AI and it can make mistakes

Arps' equation describes how a well's or field's rate falls over time:

    q(t) = qi / (1 + b * Di * t) ** (1 / b)     hyperbolic, 0 < b < 1
    q(t) = qi * exp(-Di * t)                     exponential, b = 0
    q(t) = qi / (1 + Di * t)                     harmonic, b = 1

qi is the starting rate, Di the starting decline rate per month, and b how
quickly the decline itself slows down. Time t is in months from the start
of the fit window.

The fit is done on log(rate), so a month at 3,000 Sm3/day and a month at
300 Sm3/day count equally. Fitting raw rates would let the early, high
months dominate.
"""
from dataclasses import dataclass
from enum import Enum

import numpy as np
from scipy.optimize import curve_fit

DAYS_PER_MONTH = 365.25 / 12
SM3_TO_BBL = 6.2898
MAX_FORECAST_MONTHS = 600  # stop looking for the economic limit after 50 years
B_MIN, B_MAX = 0.01, 1.0  # range the hyperbolic fit may choose b from

class Model(str, Enum):
    exponential = "exponential"
    hyperbolic = "hyperbolic"
    harmonic = "harmonic"


def arps(t: np.ndarray, qi: float, di: float, b: float) -> np.ndarray:
    t = np.asarray(t, dtype=float)
    if b < 1e-6:
        return qi * np.exp(-di * t)
    return qi / np.power(1.0 + b * di * t, 1.0 / b)


@dataclass(frozen=True)
class Fit:
    model: Model
    qi: float          # Sm3/day at the start of the window
    di: float          # nominal decline per month at the start of the window
    b: float
    r2: float          # in log space
    sigma: float       # standard deviation of log residuals
    n: int             # months used

    def rate(self, t) -> np.ndarray:
        return arps(t, self.qi, self.di, self.b)

    @property
    def b_at_limit(self) -> bool:
        """True when a hyperbolic fit pushed b to the edge of its allowed range.

        At the low edge the data is really exponential, at the high edge really
        harmonic, so the fitted b is a limit, not a measured value.
        """
        if self.model is not Model.hyperbolic:
            return False
        return self.b <= B_MIN + 1e-3 or self.b >= B_MAX - 1e-3

    @property
    def di_annual_pct(self) -> float:
        """Nominal annual decline rate at the start of the window, in percent."""
        return self.di * 12 * 100


def fit(t: np.ndarray, q: np.ndarray, model: Model) -> Fit:
    """Fit Arps to rates q (Sm3/day) at times t (months from window start)."""
    t = np.asarray(t, dtype=float)
    q = np.asarray(q, dtype=float)
    keep = q > 0
    t, q = t[keep], q[keep]
    if len(q) < 6:
        raise ValueError("need at least 6 months with production to fit a decline curve")

    y = np.log(q)
    qi0 = float(q[: min(3, len(q))].mean())
    # starting guess for Di from a straight line through log(q)
    slope = np.polyfit(t, y, 1)[0]
    di0 = float(min(max(-slope, 1e-3), 1.0))

    if model is Model.hyperbolic:
        f = lambda tt, lqi, di, b: np.log(arps(tt, np.exp(lqi), di, b))
        p, _ = curve_fit(f, t, y, p0=[np.log(qi0), di0, 0.5],
                         bounds=([np.log(qi0) - 3, 1e-5, B_MIN], [np.log(qi0) + 3, 5.0, B_MAX]), maxfev=20000)
        lqi, di, b = p  # <- this line
    else:
        b = 0.0 if model is Model.exponential else 1.0
        f = lambda tt, lqi, di: np.log(arps(tt, np.exp(lqi), di, b))
        p, _ = curve_fit(f, t, y, p0=[np.log(qi0), di0],
                         bounds=([np.log(qi0) - 3, 1e-5], [np.log(qi0) + 3, 5.0]), maxfev=20000)
        lqi, di = p

    resid = y - np.log(arps(t, np.exp(lqi), di, b))
    ss_res = float(np.sum(resid ** 2))
    ss_tot = float(np.sum((y - y.mean()) ** 2))
    n_params = 3 if model is Model.hyperbolic else 2
    sigma = float(np.sqrt(ss_res / max(len(y) - n_params, 1)))
    return Fit(model=model, qi=float(np.exp(lqi)), di=float(di), b=float(b),
               r2=1 - ss_res / ss_tot if ss_tot > 0 else 1.0, sigma=sigma, n=len(y))


def band(fit_: Fit, t: np.ndarray, t_end: float, z: float = 1.96) -> tuple[np.ndarray, np.ndarray]:
    """Rough 95% range around a forecast.

    Built from the scatter of the fit, and widened the further the forecast
    reaches past the fit window. It shows how uncertain the forecast is,
    not a formal statistical interval.
    """
    t = np.asarray(t, dtype=float)
    ahead = np.clip(t - t_end, 0, None)
    spread = z * fit_.sigma * np.sqrt(1 + ahead / max(fit_.n, 1))
    mid = fit_.rate(t)
    return mid * np.exp(-spread), mid * np.exp(spread)


def remaining_to_limit(fit_: Fit, t_end: float, economic_limit: float) -> tuple[float, int | None]:
    """Oil left after t_end until the rate drops below the limit.

    Returns (million barrels, months until the limit). Months is None if the
    rate never drops below the limit within 50 years.
    """
    t = t_end + np.arange(1, MAX_FORECAST_MONTHS + 1)
    q = fit_.rate(t)
    below = np.nonzero(q < economic_limit)[0]
    months = int(below[0]) if len(below) else None
    used = q[: months] if months is not None else q
    mmbbl = float(used.sum() * DAYS_PER_MONTH * SM3_TO_BBL / 1e6)
    return mmbbl, months